// Realm bounty_panel is a public bounty board whose resolution
// authority is separated from its funding authority.
//
// A funder escrows GNOT behind a bounty and, AT CREATION, names a panel
// of resolvers and an M-of-N threshold. Contributors submit work
// on-chain during a submission window. After that window closes the
// panel votes on the competing submissions, and the first submission to
// reach M votes wins the escrow. Neither the panel nor the threshold can
// change after creation.
//
// WHY THIS EXISTS (see DISCOVERY.md): the sibling realm `grants` already
// implements escrowed rewards, on-chain submissions, restricted award
// and a permissionless refund valve — but there the resolver IS the
// funder. On a public bounty with open submissions that is the wrong
// trust model: the deciding party has a financial interest in the
// outcome and sees every submission before deciding. This realm exists
// for exactly that delta and reuses everything else.
//
// COMPOSITION: all balance accounting is delegated to feeledger, all
// coin movement to coinio, and all free-text render output to the
// ecosystem sanitizer p/nt/markdown/sanitize/v0. This realm owns only
// the bounty state machine: bounty records, panels, submissions, votes,
// open-escrow total, deadlines, and roles.
//
// LIFECYCLE (terminal states are frozen; one transition per bounty):
//
//	CreateBounty (EOA + -send)  : escrow -> openTotal, status Open;
//	                              panel + threshold + fee bps all
//	                              SNAPSHOTTED at creation
//	Submit (also re-submit)     : while Open and height <
//	                              submitDeadline; keyed by the caller's
//	                              own address; funder and panel barred
//	Vote (panel only)           : while Open and submitDeadline <=
//	                              height < resolveDeadline; one live
//	                              vote per resolver, changeable until
//	                              the threshold is reached; the Mth vote
//	                              for a submission awards the bounty
//	                              ATOMICALLY (Open -> Awarded)
//	CancelBounty (funder only)  : Open -> Cancelled, fee-free refund —
//	                              ONLY while no submission exists
//	ExpireBounty (ANYONE)       : Open -> Expired once height >=
//	                              resolveDeadline + ExpiryGraceBlocks;
//	                              fee-free refund to the funder — the
//	                              permissionless valve against a panel
//	                              that never resolves (but see THE ONE
//	                              CAVEAT below)
//	Claim / ClaimAll (anyone)   : pays out the caller's own ledger
//	                              balance (winnings and refunds)
//	WithdrawFees (fee recipient): pays out the fee pot
//
// WHY THE WINDOWS DO NOT OVERLAP: submissions close at submitDeadline
// and voting opens at the same height. A resolver therefore votes only
// on content that can no longer change, which removes the bait-and-
// switch where a submission collects votes and is then edited. It also
// means no submission can be added in response to the votes already
// cast.
//
// THE ONE CAVEAT ON THE EXPIRY VALVE, stated rather than glossed: both
// ways out of an Open bounty — award and refund — credit the shared
// feeledger, so both fail while that ledger is saturated at the int64
// boundary, and the escrow is temporarily immovable in BOTH directions
// until some account claims down. Nothing is lost and the valve works
// again as soon as the ledger has headroom (this is exercised in
// TestSaturatedAwardCannotTrapFunds). The state requires liabilities
// within ~50 of 2^63-1 ugnot, which exceeds the real GNOT supply by
// orders of magnitude and is unreachable absent a chain-level minting
// bug, since every credit is backed by an escrowed -send. So: the
// valve makes fund-trapping impossible under any reachable condition,
// which is a weaker claim than "impossible" and is the true one.
//
// WHY CANCEL IS RESTRICTED: in `grants` the creator may cancel at any
// time while open. Here, once a single contributor has submitted work,
// the funder can no longer unilaterally reclaim the escrow — only the
// panel (by awarding) or the expiry valve (after the resolution window)
// can end the bounty. This is the concrete anti-harvest guarantee that
// a public bounty needs and a grant programme does not.
//
// AUTHORIZATION: every identity is derived from the crossing
// entrypoint's cur.Previous().Address() — no function takes a caller
// identity as a parameter. Submissions, votes and claimable balances
// are keyed by that runtime-derived address, so altering another user's
// submission, casting another resolver's vote, or claiming another
// user's winnings is impossible by construction.
//
// PANEL INTEGRITY, fixed at creation and immutable thereafter: the
// panel is non-empty, free of duplicates, every member is a valid
// bech32 address, and 1 <= threshold <= panelSize. Panel members may
// not submit work, so a resolver cannot vote for their own submission.
// The funder MAY be a panel member — barring them would be
// unenforceable theatre (a funder can always name an address they
// control), and the panel is public on-chain from creation, so a
// self-resolved bounty is visible to contributors BEFORE they spend
// effort. Disclosure beats a prohibition that cannot be enforced.
//
// FEE MODEL: fee = floor(amount * bps / 10000), rounding favors the
// winner; no minimum fee; bps snapshotted into the bounty at creation,
// so SetFeeBps affects future bounties only (closes the award-time
// admin race), and CreateBounty takes the caller's own maxFeeBps
// ceiling, rejecting creation if the live fee exceeds what the funder
// signed for (closes the creation-time race); hard compile-time cap
// MaxFeeBps (10%); refunds (cancel/expire) are always fee-free.
//
// MONETARY INVARIANT (conservation): let H be ugnot held at this
// realm's address, B = openTotal (Σ amount over Open bounties), U the
// ledger's claimable balances, F the fee pot, S >= 0 out-of-band
// surplus:
//
//	H == B + U + F + S
//
// Every transition moves value between exactly two terms inside one
// transaction: CreateBounty raises H and B together (coinio.Receive is
// the receipt-guaranteed shape); award/cancel/expire move amount from B
// into U+F with feeledger guaranteeing credited + fee == amount; claims
// and fee withdrawal debit the ledger before coinio.Payout moves the
// identical amount out (checks-effects-interactions); any panic aborts
// the whole transaction; this realm never issues or removes coins.
// Surplus is recoverable only via SweepDenom (fee recipient), which
// reserves Liabilities() = B + U + F.
//
// ONLY GNOT: CreateBounty rejects any envelope that is not exactly one
// positive ugnot coin (coinio.Receive). Every other entrypoint rejects
// attached coins outright rather than converting them to sweepable
// surplus.
package bounty_panel

import (
	"chain"
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"
	"strings"

	"gno.land/p/g1ut6uspuh73e02yauxpmyt8g3wwddaq8utagvm3/coinio"
	"gno.land/p/g1ut6uspuh73e02yauxpmyt8g3wwddaq8utagvm3/feeledger"
	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/markdown/sanitize/v0"
)

// RealmPath is this realm's own path, used to build Render links.
const RealmPath = "/r/g1ut6uspuh73e02yauxpmyt8g3wwddaq8utagvm3/bounty_panel"

// Denom is the only asset this realm accepts.
const Denom = "ugnot"

// MaxFeeBps is the hard protocol-fee cap: 1000 bps = 10%.
const MaxFeeBps = int64(1000)

// Bounty status values.
const (
	StatusOpen      = "open"
	StatusAwarded   = "awarded"
	StatusCancelled = "cancelled"
	StatusExpired   = "expired"
)

// Input bounds.
const (
	MaxTitleLen = 80
	MaxDescLen  = 2000

	// MaxURILen bounds a submission's content reference. Submissions
	// carry a REFERENCE (a URL or content hash), not the work itself —
	// the chain cannot judge quality, and storing bulk content would
	// push an unbounded cost onto every future reader of this realm.
	MaxURILen = 500

	// MaxPanelSize bounds panel parsing, storage and Render cost.
	MaxPanelSize = int64(16)

	// MaxSubmissions bounds per-bounty state growth. Each submission
	// also costs its submitter a storage deposit, so this is a ceiling
	// on a cost that is already borne by the party creating it.
	MaxSubmissions = int64(500)

	// MinDurationBlocks / MaxDurationBlocks bound each configurable
	// window (~5s blocks: 1 block to ~580 days).
	MinDurationBlocks = int64(1)
	MaxDurationBlocks = int64(10_000_000)

	// ExpiryGraceBlocks after the resolution deadline, an Open bounty
	// becomes expirable by anyone (~8 minutes at 5s blocks — short
	// because this is a testnet deployment; a production fork would
	// raise it). The grace exists so that "the panel may still vote"
	// and "anyone may expire" are never simultaneously true.
	ExpiryGraceBlocks = int64(100)

	// MaxRenderRows bounds Render output. Render is reachable by any
	// viewer through gnoweb and vm/qrender, so its cost lands on third
	// parties rather than on whoever grew the state.
	MaxRenderRows = 20
)

type submission struct {
	uri    string // content reference (URL or hash)
	height int64  // block height of the latest (re)submission
	votes  int64  // live panel votes currently naming this submission
}

type bounty struct {
	id          int64
	funder      address
	title       string
	description string
	amount      int64
	feeBps      int64 // snapshotted at creation, charged at award

	panel     *avl.Tree // resolver address string -> struct{}{}
	panelSize int64
	threshold int64 // votes required to award (1 <= threshold <= panelSize)

	submitDeadline  int64 // submissions close here; voting opens here
	resolveDeadline int64 // voting closes here

	status string
	winner address // set iff status == StatusAwarded

	subs    *avl.Tree // submitter address string -> *submission
	numSubs int64
	ballots *avl.Tree // resolver address string -> submitter address string
}

var (
	admin        address // may set fee, fee recipient, successor admin
	feeRecipient address // may withdraw fees and sweep surplus
	feeBps       int64   // fee snapshotted into NEW bounties

	self      address // this realm's address, captured at deploy
	nextID    int64
	openTotal int64 // == Σ amount over bounties with status Open

	bounties = avl.NewTree() // padID(id) -> *bounty
	ledger   = feeledger.MustNew(MaxFeeBps)
)

func init() {
	admin = unsafe.OriginCaller()
	feeRecipient = admin
	self = unsafe.CurrentRealm().Address()
}

// rejectStraySend aborts when coins are attached to a non-payable call.
// This realm does hold funds, so a stray send would not be lost outright
// — it would become sweepable surplus belonging to the fee recipient,
// silently converting a user's coins into protocol revenue. Aborting
// reverts the transfer to the sender instead. Guarded on IsUserCall, not
// IsUser, because a MsgRun ephemeral can consume the OriginSend envelope
// before forwarding control.
//
// SCOPE, precisely: the guard reads the ORIGINATING transaction's
// envelope, so it only inspects direct EOA calls. For a realm-routed
// call the -send envelope is delivered to the INTERMEDIARY realm's
// address, so there is nothing at this realm to reject and the guard
// deliberately fails open. That is not a hole: an intermediary that
// separately sends coins to this realm's address is making an ordinary
// transfer, which no guard in any entrypoint could intercept, and
// which lands as surplus recoverable through SweepDenom. Coins can
// only become ESCROW through CreateBounty.
func rejectStraySend(cur realm) {
	if cur.Previous().IsUserCall() && len(unsafe.OriginSend()) > 0 {
		panic("this entrypoint does not accept coins")
	}
}

// CreateBounty escrows the attached GNOT as a new open bounty and
// returns its id. Only direct EOA calls with -send are accepted.
//
// panelCSV is a comma-separated list of resolver addresses; threshold is
// how many of them must name the same submission for it to win.
// Submissions are accepted for submitBlocks from now, after which the
// panel has resolveBlocks to decide.
//
// The current protocol fee is snapshotted into the bounty and must not
// exceed maxFeeBps, the ceiling the caller signed for; pass MaxFeeBps to
// accept any legal fee.
func CreateBounty(cur realm, title, description, panelCSV string, threshold, submitBlocks, resolveBlocks, maxFeeBps int64) int64 {
	funder, amount := coinio.Receive(0, cur, Denom)
	if feeBps > maxFeeBps {
		panic("current fee " + itoa(feeBps) + " bps exceeds the caller's maximum " + itoa(maxFeeBps))
	}
	assertValidTitle(title)
	if len(description) == 0 || len(description) > MaxDescLen {
		panic("description must be 1-" + strconv.Itoa(MaxDescLen) + " bytes")
	}
	assertDuration("submitBlocks", submitBlocks)
	assertDuration("resolveBlocks", resolveBlocks)

	panel, panelSize := parsePanel(panelCSV)
	if threshold < 1 || threshold > panelSize {
		panic("threshold must be in [1, panel size " + itoa(panelSize) + "]")
	}

	newOpenTotal, ok := checkedAdd(openTotal, amount)
	if !ok {
		panic("open escrow overflow")
	}

	now := runtime.ChainHeight()
	nextID++
	b := &bounty{
		id:              nextID,
		funder:          funder,
		title:           title,
		description:     description,
		amount:          amount,
		feeBps:          feeBps,
		panel:           panel,
		panelSize:       panelSize,
		threshold:       threshold,
		submitDeadline:  now + submitBlocks,
		resolveDeadline: now + submitBlocks + resolveBlocks,
		status:          StatusOpen,
		subs:            avl.NewTree(),
		ballots:         avl.NewTree(),
	}
	bounties.Set(padID(b.id), b)
	openTotal = newOpenTotal

	chain.Emit("BountyCreated",
		"id", itoa(b.id),
		"funder", funder.String(),
		"amount", itoa(amount),
		"feeBps", itoa(b.feeBps),
		"panelSize", itoa(panelSize),
		"threshold", itoa(threshold),
		"submitDeadline", itoa(b.submitDeadline),
		"resolveDeadline", itoa(b.resolveDeadline),
	)
	return b.id
}

// Submit records (or replaces) the caller's submission to an open bounty
// before its submission deadline. One submission per address per bounty
// — re-submitting replaces the caller's own reference only. The funder
// and every panel member are barred, so no resolver can vote for their
// own work.
func Submit(cur realm, id int64, uri string) {
	rejectStraySend(cur)
	submitter := cur.Previous().Address()
	b := mustGetBounty(id)
	if b.status != StatusOpen {
		panic("bounty is not open")
	}
	if runtime.ChainHeight() >= b.submitDeadline {
		panic("submission window has closed")
	}
	if submitter == b.funder {
		panic("the funder cannot submit to their own bounty")
	}
	if b.panel.Has(submitter.String()) {
		panic("a panel resolver cannot submit to a bounty they judge")
	}
	if len(uri) == 0 || len(uri) > MaxURILen {
		panic("uri must be 1-" + strconv.Itoa(MaxURILen) + " bytes")
	}

	key := submitter.String()
	if v := b.subs.Get(key); v != nil {
		s := v.(*submission)
		s.uri = uri
		s.height = runtime.ChainHeight()
	} else {
		if b.numSubs >= MaxSubmissions {
			panic("bounty has reached its submission cap")
		}
		b.numSubs++
		b.subs.Set(key, &submission{uri: uri, height: runtime.ChainHeight()})
	}

	chain.Emit("Submitted", "id", itoa(id), "submitter", key)
}

// Vote casts (or changes) the calling resolver's vote for one of the
// bounty's submissions. Only panel members may vote, and only after the
// submission window has closed and before the resolution deadline. A
// resolver holds exactly one live vote, changeable until the threshold
// is reached.
//
// The vote that brings a submission to the threshold awards the bounty
// in the same transaction: the escrow leaves the open pool and is
// credited to the winner's claimable balance at the fee snapshotted at
// creation. Terminal.
func Vote(cur realm, id int64, candidate address) {
	rejectStraySend(cur)
	resolver := cur.Previous().Address()
	b := mustGetBounty(id)
	if b.status != StatusOpen {
		panic("bounty is not open")
	}
	if !b.panel.Has(resolver.String()) {
		panic("only a panel resolver may vote")
	}
	now := runtime.ChainHeight()
	if now < b.submitDeadline {
		panic("voting opens when the submission window closes")
	}
	if now >= b.resolveDeadline {
		panic("resolution window has closed")
	}

	candKey := candidate.String()
	cv := b.subs.Get(candKey)
	if cv == nil {
		panic("candidate must have submitted to this bounty")
	}
	cand := cv.(*submission)

	rKey := resolver.String()
	if prev := b.ballots.Get(rKey); prev != nil {
		prevKey := prev.(string)
		if prevKey == candKey {
			panic("already voted for this submission")
		}
		// Withdraw the resolver's previous vote before recording the new
		// one, so the per-submission counts always sum to the number of
		// live ballots.
		pv := b.subs.Get(prevKey)
		pv.(*submission).votes--
	}
	b.ballots.Set(rKey, candKey)
	cand.votes++

	chain.Emit("Voted",
		"id", itoa(id),
		"resolver", rKey,
		"candidate", candKey,
		"votes", itoa(cand.votes),
		"threshold", itoa(b.threshold),
	)

	if cand.votes >= b.threshold {
		award(b, candidate, cand.votes)
	}
}

// award moves an Open bounty's escrow into the winner's claimable
// balance at the snapshotted fee and finalizes the status. The caller
// has already verified authorization, status and the threshold.
func award(b *bounty, winner address, votes int64) {
	credited, fee, err := ledger.Deposit(winner.String(), b.amount, b.feeBps)
	if err != nil {
		panic(err)
	}
	openTotal -= b.amount // >= 0: openTotal == Σ open amounts >= b.amount
	b.status = StatusAwarded
	b.winner = winner

	chain.Emit("BountyAwarded",
		"id", itoa(b.id),
		"winner", winner.String(),
		"credited", itoa(credited),
		"fee", itoa(fee),
		"votes", itoa(votes),
	)
}

// CancelBounty closes an open bounty and refunds its escrow to the
// funder, fee-free. Only the funder may cancel, and ONLY while no
// contributor has submitted: once work exists, the funder cannot
// unilaterally reclaim the escrow. Terminal.
func CancelBounty(cur realm, id int64) {
	rejectStraySend(cur)
	caller := cur.Previous().Address()
	b := mustGetBounty(id)
	if caller != b.funder {
		panic("only the bounty funder may cancel")
	}
	if b.status != StatusOpen {
		panic("bounty is not open")
	}
	if b.numSubs > 0 {
		panic("cannot cancel a bounty that has submissions; it must be resolved or expire")
	}
	refundOpen(b, StatusCancelled)
	chain.Emit("BountyCancelled", "id", itoa(id), "funder", b.funder.String(), "amount", itoa(b.amount))
}

// ExpireBounty closes an open bounty whose resolution deadline passed
// more than ExpiryGraceBlocks ago, refunding the funder fee-free. ANYONE
// may call it — this is the permissionless valve that guarantees escrow
// can never be trapped by an inactive or deadlocked panel. Terminal.
func ExpireBounty(cur realm, id int64) {
	rejectStraySend(cur)
	b := mustGetBounty(id)
	if b.status != StatusOpen {
		panic("bounty is not open")
	}
	if runtime.ChainHeight() < b.resolveDeadline+ExpiryGraceBlocks {
		panic("bounty is not expirable yet")
	}
	refundOpen(b, StatusExpired)
	chain.Emit("BountyExpired", "id", itoa(b.id), "funder", b.funder.String(), "amount", itoa(b.amount))
}

// refundOpen moves an Open bounty's escrow into the funder's claimable
// balance fee-free and finalizes the status. Callers have already
// verified authorization and status.
func refundOpen(b *bounty, terminal string) {
	if _, _, err := ledger.Deposit(b.funder.String(), b.amount, 0); err != nil {
		panic(err)
	}
	openTotal -= b.amount
	b.status = terminal
}

// Claim sends amount ugnot of the caller's claimable balance (winnings
// and refunds) back to the caller.
func Claim(cur realm, amount int64) {
	rejectStraySend(cur)
	caller := cur.Previous().Address()
	if err := ledger.Withdraw(caller.String(), amount); err != nil {
		panic(err)
	}
	coinio.Payout(0, cur, caller, Denom, amount)
	chain.Emit("Claim", "to", caller.String(), "amount", itoa(amount))
}

// ClaimAll sends the caller's entire claimable balance back to the
// caller. Fails if there is nothing to claim.
func ClaimAll(cur realm) {
	rejectStraySend(cur)
	caller := cur.Previous().Address()
	amount, err := ledger.WithdrawAll(caller.String())
	if err != nil {
		panic(err)
	}
	if amount == 0 {
		panic("nothing to claim")
	}
	coinio.Payout(0, cur, caller, Denom, amount)
	chain.Emit("Claim", "to", caller.String(), "amount", itoa(amount))
}

// WithdrawFees sends the accrued fee pot to the fee recipient. Only the
// fee recipient may call it.
func WithdrawFees(cur realm) {
	rejectStraySend(cur)
	caller := cur.Previous().Address()
	if caller != feeRecipient {
		panic("only the fee recipient may withdraw fees")
	}
	if ledger.FeesAccrued() == 0 {
		panic("no fees accrued")
	}
	amount := ledger.WithdrawFees()
	coinio.Payout(0, cur, feeRecipient, Denom, amount)
	chain.Emit("FeesWithdrawn", "to", feeRecipient.String(), "amount", itoa(amount))
}

// SweepDenom sends the surplus of a single denomination to the fee
// recipient. For ugnot only the excess over Liabilities() moves; other
// denoms move wholly. Only the fee recipient may call it.
func SweepDenom(cur realm, denom string) {
	rejectStraySend(cur)
	caller := cur.Previous().Address()
	if caller != feeRecipient {
		panic("only the fee recipient may sweep surplus")
	}
	reserve := int64(0)
	if denom == Denom {
		reserve = Liabilities()
	}
	swept := coinio.Sweep(0, cur, feeRecipient, denom, reserve)
	chain.Emit("SurplusSwept", "to", feeRecipient.String(), "coins", itoa(swept)+denom)
}

// SetFeeBps sets the protocol fee snapshotted into FUTURE bounties at
// creation. Existing bounties keep the fee they were created under.
// Admin only; bounded by [0, MaxFeeBps].
func SetFeeBps(cur realm, bps int64) {
	rejectStraySend(cur)
	assertAdmin(cur.Previous().Address())
	if bps < 0 || bps > MaxFeeBps {
		panic("fee bps out of range [0, " + itoa(MaxFeeBps) + "]")
	}
	old := feeBps
	feeBps = bps
	chain.Emit("FeeBpsChanged", "old", itoa(old), "new", itoa(bps))
}

// SetFeeRecipient re-points the fee/surplus role, including the pot
// accrued so far. Admin only; zero address rejected.
func SetFeeRecipient(cur realm, next address) {
	rejectStraySend(cur)
	assertAdmin(cur.Previous().Address())
	var zero address
	if next == zero {
		panic("empty fee recipient")
	}
	old := feeRecipient
	feeRecipient = next
	chain.Emit("FeeRecipientChanged", "old", old.String(), "new", next.String())
}

// TransferAdmin hands the admin role to next. Admin only; zero address
// rejected. One-step (documented trade-off, matching the siblings).
func TransferAdmin(cur realm, next address) {
	rejectStraySend(cur)
	assertAdmin(cur.Previous().Address())
	var zero address
	if next == zero {
		panic("empty admin address")
	}
	admin = next
	chain.Emit("AdminTransferred", "newAdmin", next.String())
}

// --- read-only views ---

// BountyInfo returns a bounty's scalar fields by value.
func BountyInfo(id int64) (funder address, title string, amount, feeBps, submitDeadline, resolveDeadline int64, status string, winner address, numSubmissions, panelSize, threshold int64) {
	b := mustGetBounty(id)
	return b.funder, b.title, b.amount, b.feeBps, b.submitDeadline, b.resolveDeadline, b.status, b.winner, b.numSubs, b.panelSize, b.threshold
}

// Description returns a bounty's raw description text.
func Description(id int64) string { return mustGetBounty(id).description }

// SubmissionOf returns addr's content reference, submission height and
// current vote count for a bounty, with ok reporting whether a
// submission exists.
func SubmissionOf(id int64, addr address) (uri string, height, votes int64, ok bool) {
	b := mustGetBounty(id)
	v := b.subs.Get(addr.String())
	if v == nil {
		return "", 0, 0, false
	}
	s := v.(*submission)
	return s.uri, s.height, s.votes, true
}

// IsPanelMember reports whether addr may vote on a bounty.
func IsPanelMember(id int64, addr address) bool {
	return mustGetBounty(id).panel.Has(addr.String())
}

// Panel returns a bounty's resolver addresses as a comma-separated
// list, in sorted order.
func Panel(id int64) string {
	b := mustGetBounty(id)
	out := ""
	b.panel.Iterate("", "", func(key string, _ any) bool {
		if out != "" {
			out += ","
		}
		out += key
		return false
	})
	return out
}

// VoteOf returns the submission a resolver currently votes for, with ok
// reporting whether that resolver has voted at all.
func VoteOf(id int64, resolver address) (candidate string, ok bool) {
	b := mustGetBounty(id)
	v := b.ballots.Get(resolver.String())
	if v == nil {
		return "", false
	}
	return v.(string), true
}

// VotesCast returns how many resolvers currently hold a live vote.
func VotesCast(id int64) int64 { return int64(mustGetBounty(id).ballots.Size()) }

// Admin returns the current admin.
func Admin() address { return admin }

// FeeRecipient returns who may withdraw fees and sweep surplus.
func FeeRecipient() address { return feeRecipient }

// FeeBps returns the fee that will be snapshotted into newly created
// bounties (existing bounties keep their own snapshot).
func FeeBps() int64 { return feeBps }

// FeeOn previews the fee and net payout for a bounty of amount at the
// CURRENT FeeBps.
func FeeOn(amount int64) (fee, credited int64) {
	f, err := feeledger.FeeFor(amount, feeBps)
	if err != nil {
		panic(err)
	}
	return f, amount - f
}

// NumBounties returns how many bounties have ever been created.
func NumBounties() int64 { return nextID }

// OpenTotal returns the escrow held by open bounties (the B term).
func OpenTotal() int64 { return openTotal }

// BalanceOf returns addr's claimable balance (winnings + refunds).
func BalanceOf(addr address) int64 { return ledger.BalanceOf(addr.String()) }

// UsersTotal returns the sum of all claimable balances (the U term).
func UsersTotal() int64 { return ledger.UsersTotal() }

// FeesAccrued returns the fee pot (the F term).
func FeesAccrued() int64 { return ledger.FeesAccrued() }

// Liabilities returns everything this realm owes:
// openTotal + UsersTotal + FeesAccrued.
func Liabilities() int64 { return openTotal + ledger.Liabilities() }

// Held returns the ugnot actually held at the realm address (H).
func Held() int64 { return coinio.HeldAt(self, Denom) }

// Surplus returns Held() - Liabilities() (the S term).
func Surplus() int64 { return Held() - Liabilities() }

// Address returns this realm's address (the escrow target).
func Address() address { return self }

// Height returns the current chain height (deadline arithmetic aid).
func Height() int64 { return runtime.ChainHeight() }

// Render shows the board at "" and a bounty detail at "<id>". Free text
// (titles are charset-restricted; descriptions and URIs are not) passes
// through the ecosystem sanitizer before hitting markdown.
func Render(path string) string {
	if path != "" {
		return renderBounty(path)
	}
	held := Held()
	liab := Liabilities()
	status := "OK"
	if held < liab {
		status = "VIOLATED"
	}
	out := "# Bounty panel\n\n"
	out += "Escrowed GNOT bounties resolved by a panel named at creation, not by the funder.\n\n"
	out += "## Configuration\n\n"
	out += "- fee for new bounties: " + itoa(feeBps) + " bps (cap " + itoa(MaxFeeBps) +
		" bps; each bounty keeps the fee snapshotted at its creation)\n"
	out += "- fee recipient: " + feeRecipient.String() + "\n"
	out += "- admin: " + admin.String() + "\n\n"
	out += "## Accounting (H == B + U + F + S)\n\n"
	out += "- open escrow (B): " + itoa(openTotal) + Denom + "\n"
	out += "- claimable (U): " + itoa(ledger.UsersTotal()) + Denom + "\n"
	out += "- fees accrued (F): " + itoa(ledger.FeesAccrued()) + Denom + "\n"
	out += "- held (H): " + itoa(held) + Denom + "\n"
	out += "- conservation: " + status + "\n\n"
	out += "## Latest bounties\n\n"
	if nextID == 0 {
		out += "No bounties yet.\n"
		return out
	}
	shown := 0
	bounties.ReverseIterate("", "", func(_ string, v any) bool {
		b := v.(*bounty)
		out += "- [#" + itoa(b.id) + "](" + RealmPath + ":" + itoa(b.id) + ") [" +
			b.status + "] " + b.title + " — " + itoa(b.amount) + Denom +
			" (" + itoa(b.numSubs) + " submissions, " + itoa(b.threshold) + "-of-" + itoa(b.panelSize) + ")\n"
		shown++
		return shown >= MaxRenderRows
	})
	if int64(shown) < nextID {
		out += "\n> [!NOTE]\n> Showing the " + strconv.Itoa(shown) + " most recent of " +
			itoa(nextID) + ". Use BountyInfo(id) for any specific bounty.\n"
	}
	return out
}

func renderBounty(path string) string {
	id, err := strconv.ParseInt(path, 10, 64)
	if err != nil {
		return "> [!WARNING]\n> invalid bounty id\n"
	}
	v := bounties.Get(padID(id))
	if v == nil {
		return "> [!WARNING]\n> unknown bounty id\n"
	}
	b := v.(*bounty)
	now := runtime.ChainHeight()

	out := "# Bounty #" + itoa(b.id) + ": " + b.title + "\n\n"
	out += "- status: " + b.status + "\n"
	out += "- funder: " + b.funder.String() + "\n"
	out += "- amount: " + itoa(b.amount) + Denom + "\n"
	out += "- fee (snapshot): " + itoa(b.feeBps) + " bps\n"
	out += "- resolution: " + itoa(b.threshold) + " of " + itoa(b.panelSize) + " panel votes\n"
	out += "- submissions close: block " + itoa(b.submitDeadline) + "\n"
	out += "- resolution closes: block " + itoa(b.resolveDeadline) + " (now " + itoa(now) + ")\n"
	out += "- submissions: " + itoa(b.numSubs) + "\n"
	if b.status == StatusAwarded {
		out += "- winner: " + b.winner.String() + "\n"
	}

	out += "\n## Description\n\n" + sanitize.InlineText(b.description) + "\n"

	out += "\n## Panel\n\n"
	b.panel.Iterate("", "", func(key string, _ any) bool {
		out += "- " + key + "\n"
		return false
	})

	out += "\n## Submissions\n\n"
	if b.numSubs == 0 {
		out += "No submissions yet.\n"
		return out
	}
	shown := 0
	b.subs.Iterate("", "", func(key string, sv any) bool {
		s := sv.(*submission)
		out += "- " + key + " — " + itoa(s.votes) + " vote(s), block " + itoa(s.height) +
			"\n  - " + sanitize.InlineText(s.uri) + "\n"
		shown++
		return shown >= MaxRenderRows
	})
	if int64(shown) < b.numSubs {
		out += "\n> [!NOTE]\n> Showing " + strconv.Itoa(shown) + " of " + itoa(b.numSubs) +
			" submissions. Use SubmissionOf(id, addr) for any specific one.\n"
	}
	return out
}

// --- internals ---

func assertAdmin(caller address) {
	if caller != admin {
		panic("admin only")
	}
}

func mustGetBounty(id int64) *bounty {
	v := bounties.Get(padID(id))
	if v == nil {
		panic("unknown bounty id")
	}
	return v.(*bounty)
}

func assertDuration(name string, blocks int64) {
	if blocks < MinDurationBlocks || blocks > MaxDurationBlocks {
		panic(name + " out of range [" + itoa(MinDurationBlocks) + ", " + itoa(MaxDurationBlocks) + "]")
	}
}

// parsePanel turns a comma-separated resolver list into a membership
// tree. Every entry must be a valid, non-empty, non-duplicate bech32
// address. Validity is checked here rather than trusted: a mistyped
// resolver address would silently shrink the effective panel and could
// make the threshold permanently unreachable, which is a fund-trapping
// shape even with the expiry valve in place.
func parsePanel(csv string) (*avl.Tree, int64) {
	parts := strings.Split(csv, ",")
	panel := avl.NewTree()
	count := int64(0)
	for _, p := range parts {
		key := strings.TrimSpace(p)
		if key == "" {
			panic("panel contains an empty entry")
		}
		if !address(key).IsValid() {
			panic("panel contains an invalid address: " + key)
		}
		if panel.Has(key) {
			panic("panel contains a duplicate address: " + key)
		}
		count++
		if count > MaxPanelSize {
			panic("panel exceeds " + itoa(MaxPanelSize) + " resolvers")
		}
		panel.Set(key, struct{}{})
	}
	if count == 0 {
		panic("panel must name at least one resolver")
	}
	return panel, count
}

// assertValidTitle bounds length and restricts the charset so titles are
// list-safe in Render without escaping.
func assertValidTitle(title string) {
	if len(title) == 0 || len(title) > MaxTitleLen {
		panic("title must be 1-" + strconv.Itoa(MaxTitleLen) + " characters")
	}
	for i := 0; i < len(title); i++ {
		c := title[i]
		switch {
		case c >= 'a' && c <= 'z':
		case c >= 'A' && c <= 'Z':
		case c >= '0' && c <= '9':
		case c == ' ' || c == '_' || c == '-':
		default:
			panic("title may only contain letters, digits, space, _ and -")
		}
	}
}

// padID renders an id as a fixed-width key so avl iteration order is
// numeric order.
func padID(id int64) string {
	s := strconv.FormatInt(id, 10)
	for len(s) < 12 {
		s = "0" + s
	}
	return s
}

func itoa(n int64) string {
	return strconv.FormatInt(n, 10)
}

func checkedAdd(a, b int64) (int64, bool) {
	sum := a + b
	if (b > 0 && sum < a) || (b < 0 && sum > a) {
		return 0, false
	}
	return sum, true
}

// Package duebook is a pure scheduling primitive for realms that need to
// authorize an action now and perform it later. It is to *time* what
// feeledger is to *money*: it holds no coins, performs no effects, imports
// no chain APIs, and owns no package-level state. The importing realm owns
// a *Book, supplies the clock, and performs its own effects.
//
// # The one idea
//
// A realm does not ask duebook to execute anything — Gno has no autonomous
// execution, so "scheduled" always means "someone sends a transaction
// later". What a realm actually needs is for that later transaction to be
// authorized exactly once. Claim is that step:
//
//	d, err := book.Claim(id, now)
//	if err != nil {
//		panic(err) // not due, expired, cancelled, or already claimed
//	}
//	// ... the realm performs its own effect here, under its own authority
//
// Claim checks due / not-expired / still-open and CONSUMES the deferral in
// the same call, before returning. The realm then acts. Replay is not
// guarded against, it is structurally impossible:
//
//   - IDs are allocated monotonically from an internal counter and are
//     NEVER reused, for the lifetime of the Book;
//   - a successful Claim removes the deferral before returning;
//
// so at most one Claim per ID can ever succeed, across all transactions,
// forever. A second Claim of the same ID returns ErrNotFound whether the
// first one happened in this transaction or a year ago.
//
// Because the realm performs the effect itself, no closure, callback, or
// capability ever crosses a realm boundary. duebook cannot be handed code
// to run, so it cannot be tricked into running the wrong code.
//
// # Lifecycle
//
// A deferral is open from Schedule until exactly one of Claim, Cancel, or
// Expire consumes it. There is no other transition and no way back.
//
//	Schedule ──> open ──┬── Claim   (now >= DueAt, before ExpiresAt)
//	                    ├── Cancel  (owner only, any time while open)
//	                    └── Expire  (anyone, once now >= ExpiresAt)
//
// Claimability is the half-open interval [DueAt, ExpiresAt): due at DueAt,
// no longer claimable at ExpiresAt. A deferral scheduled with ttl == 0
// never expires and has ExpiresAt == 0.
//
// # State growth
//
// Consumed deferrals are removed, not archived — the ID counter, not a
// tombstone, is what prevents replay, so there is nothing to keep. Open
// deferrals are capped per Book at construction. Storage is therefore
// bounded by maxOpen regardless of how many deferrals have ever existed.
// Audit history belongs in the consuming realm's events.
//
// # Consumer contract (the parts the package cannot enforce)
//
//  1. SUPPLY A REAL CLOCK. duebook cannot verify that `now` came from
//     runtime.ChainHeight() or time.Now().Unix(). A realm that lets a caller
//     choose `now` has no delay at all. Pass the chain's clock, never a
//     transaction parameter. This is the single most important obligation
//     and the one most commonly got wrong.
//  2. USE ONE CLOCK CONSISTENTLY. Heights and seconds must not be mixed
//     within a Book; delay, ttl and now are all in the caller's chosen
//     unit.
//  3. DO NOT EXPORT THE BOOK. A *Book is a mutable handle. Returning one
//     across a realm boundary hands out the right to schedule, cancel and
//     claim. Expose your own crossing functions instead; this package
//     returns Deferral values, never pointers into its state.
//  4. AUTHORIZE THE ACTOR. duebook authenticates nothing but ownership on
//     Cancel. Who may Schedule, and who may Claim, are the realm's policy —
//     derive the caller from cur.Previous().Address(), not from an argument.
//  5. ACT AFTER A SUCCESSFUL CLAIM, IN THE SAME TRANSACTION. Claim's
//     return value is the authorization. Storing it to act on later
//     reintroduces the replay window this package exists to close.
//
// All failures are returned as errors and leave the Book COMPLETELY
// UNCHANGED. Must* wrappers are the only functions here that panic.
//
// The Book is address-agnostic: owners are non-empty strings. Realms
// normally use address.String().
package duebook

import (
	"errors"
	"strconv"

	"gno.land/p/nt/avl/v0"
)

// MaxPayloadLen bounds a single deferral's payload. The payload is opaque
// to duebook — it exists so a realm can recover what it scheduled without
// keeping a parallel table.
const MaxPayloadLen = 4096

// MaxOpenLimit is the largest maxOpen a Book may be constructed with. It
// bounds the worst-case cost of Due and IterateOpen, which scan the open
// set.
const MaxOpenLimit = 10000

// Errors returned by Book operations.
var (
	ErrEmptyOwner    = errors.New("duebook: empty owner key")
	ErrPayloadTooBig = errors.New("duebook: payload exceeds MaxPayloadLen")
	ErrInvalidNow    = errors.New("duebook: now must be non-negative")
	ErrInvalidDelay  = errors.New("duebook: delay outside [minDelay, maxDelay]")
	ErrInvalidTTL    = errors.New("duebook: ttl must be non-negative")
	ErrInvalidConfig = errors.New("duebook: invalid book configuration")
	ErrBookFull      = errors.New("duebook: open deferral cap reached")
	ErrNotFound      = errors.New("duebook: no such open deferral")
	ErrNotDue        = errors.New("duebook: not due yet")
	ErrExpired       = errors.New("duebook: deferral has expired")
	ErrNotExpired    = errors.New("duebook: deferral has not expired")
	ErrNotOwner      = errors.New("duebook: caller does not own this deferral")
	ErrOverflow      = errors.New("duebook: int64 overflow")
	ErrIDExhausted   = errors.New("duebook: identifier space exhausted")
)

// Deferral is a scheduled action. It is returned BY VALUE: holders cannot
// reach into a Book through it. Payload is opaque to this package.
//
// ExpiresAt == 0 means the deferral never expires. Otherwise the deferral
// is claimable exactly on [DueAt, ExpiresAt).
type Deferral struct {
	ID        uint64
	Owner     string
	Payload   string
	CreatedAt int64
	DueAt     int64
	ExpiresAt int64
}

// IsDue reports whether the deferral has reached its due time at now.
func (d Deferral) IsDue(now int64) bool { return now >= d.DueAt }

// IsExpired reports whether the deferral is past its expiry at now.
// A deferral with no expiry is never expired.
func (d Deferral) IsExpired(now int64) bool {
	return d.ExpiresAt != 0 && now >= d.ExpiresAt
}

// IsClaimable reports whether Claim would succeed at now, assuming the
// deferral is still open.
func (d Deferral) IsClaimable(now int64) bool {
	return d.IsDue(now) && !d.IsExpired(now)
}

// Book holds the open deferrals of one consuming realm. The zero value is
// not usable; construct with New.
type Book struct {
	minDelay int64
	maxDelay int64
	maxOpen  int
	nextID   uint64    // never decreases; IDs are never reused
	open     *avl.Tree // padded id -> Deferral
}

// New returns an empty Book.
//
// minDelay is the floor on how far ahead a deferral may be scheduled; 0
// permits same-instant scheduling. maxDelay is the ceiling, and doubles as
// the overflow guard on now+delay. maxOpen caps simultaneously open
// deferrals and must be in [1, MaxOpenLimit].
//
// Units are the caller's choice — block heights or seconds — but must be
// used consistently for the life of the Book.
func New(minDelay, maxDelay int64, maxOpen int) (*Book, error) {
	if minDelay < 0 || maxDelay < minDelay {
		return nil, ErrInvalidConfig
	}
	if maxOpen < 1 || maxOpen > MaxOpenLimit {
		return nil, ErrInvalidConfig
	}
	return &Book{
		minDelay: minDelay,
		maxDelay: maxDelay,
		maxOpen:  maxOpen,
		nextID:   1,
		open:     avl.NewTree(),
	}, nil
}

// MustNew is New but panics on error.
func MustNew(minDelay, maxDelay int64, maxOpen int) *Book {
	b, err := New(minDelay, maxDelay, maxOpen)
	if err != nil {
		panic(err)
	}
	return b
}

// MinDelay returns the Book's scheduling floor.
func (b *Book) MinDelay() int64 { return b.minDelay }

// MaxDelay returns the Book's scheduling ceiling.
func (b *Book) MaxDelay() int64 { return b.maxDelay }

// MaxOpen returns the Book's cap on simultaneously open deferrals.
func (b *Book) MaxOpen() int { return b.maxOpen }

// OpenCount returns how many deferrals are currently open.
func (b *Book) OpenCount() int { return b.open.Size() }

// NextID returns the identifier the next Schedule will allocate. It only
// ever increases, which is what makes a consumed ID unreusable.
func (b *Book) NextID() uint64 { return b.nextID }

// Schedule opens a deferral owned by owner, due at now+delay, expiring
// ttl after that (ttl == 0 means it never expires). It returns the new
// deferral's ID.
//
// Fails with ErrEmptyOwner, ErrPayloadTooBig, ErrInvalidNow (now < 0),
// ErrInvalidDelay (delay outside [MinDelay, MaxDelay]), ErrInvalidTTL
// (ttl < 0), ErrBookFull, ErrOverflow, or ErrIDExhausted. On error
// nothing is modified.
func (b *Book) Schedule(owner, payload string, now, delay, ttl int64) (uint64, error) {
	if owner == "" {
		return 0, ErrEmptyOwner
	}
	if len(payload) > MaxPayloadLen {
		return 0, ErrPayloadTooBig
	}
	if now < 0 {
		return 0, ErrInvalidNow
	}
	if delay < b.minDelay || delay > b.maxDelay {
		return 0, ErrInvalidDelay
	}
	if ttl < 0 {
		return 0, ErrInvalidTTL
	}
	if b.open.Size() >= b.maxOpen {
		return 0, ErrBookFull
	}
	if b.nextID == 0 {
		return 0, ErrIDExhausted
	}

	dueAt, ok := checkedAdd(now, delay)
	if !ok {
		return 0, ErrOverflow
	}
	expiresAt := int64(0)
	if ttl > 0 {
		expiresAt, ok = checkedAdd(dueAt, ttl)
		if !ok {
			return 0, ErrOverflow
		}
	}

	id := b.nextID
	b.nextID++
	b.open.Set(idKey(id), Deferral{
		ID:        id,
		Owner:     owner,
		Payload:   payload,
		CreatedAt: now,
		DueAt:     dueAt,
		ExpiresAt: expiresAt,
	})
	return id, nil
}

// MustSchedule is Schedule but panics on error.
func (b *Book) MustSchedule(owner, payload string, now, delay, ttl int64) uint64 {
	id, err := b.Schedule(owner, payload, now, delay, ttl)
	if err != nil {
		panic(err)
	}
	return id
}

// Claim consumes the deferral and returns it, authorizing the caller to
// perform the deferred action NOW, in this transaction.
//
// It succeeds only while the deferral is open and now is in
// [DueAt, ExpiresAt). The deferral is removed BEFORE Claim returns, so a
// re-entrant or later Claim of the same ID finds nothing; combined with
// non-reused IDs, at most one Claim per ID ever succeeds.
//
// Fails with ErrInvalidNow, ErrNotFound (never existed, or already
// consumed by Claim/Cancel/Expire), ErrNotDue, or ErrExpired. On error
// nothing is modified.
//
// duebook does NOT check who is claiming: whether a deferral is
// permissionlessly claimable or restricted to its owner is the consuming
// realm's policy, applied before calling Claim.
func (b *Book) Claim(id uint64, now int64) (Deferral, error) {
	if now < 0 {
		return Deferral{}, ErrInvalidNow
	}
	d, ok := b.get(id)
	if !ok {
		return Deferral{}, ErrNotFound
	}
	if !d.IsDue(now) {
		return Deferral{}, ErrNotDue
	}
	if d.IsExpired(now) {
		return Deferral{}, ErrExpired
	}
	// Consume before returning: the caller acts only after this point, so
	// the deferral is already gone when the effect runs.
	b.open.Remove(idKey(id))
	return d, nil
}

// MustClaim is Claim but panics on error.
func (b *Book) MustClaim(id uint64, now int64) Deferral {
	d, err := b.Claim(id, now)
	if err != nil {
		panic(err)
	}
	return d
}

// Cancel consumes an open deferral without performing it. Only its owner
// may cancel, and cancellation is permitted at any time while the deferral
// is open — including after it became due but before anyone claimed it.
//
// Fails with ErrEmptyOwner, ErrNotFound, or ErrNotOwner. On error nothing
// is modified.
func (b *Book) Cancel(id uint64, owner string) (Deferral, error) {
	if owner == "" {
		return Deferral{}, ErrEmptyOwner
	}
	d, ok := b.get(id)
	if !ok {
		return Deferral{}, ErrNotFound
	}
	if d.Owner != owner {
		return Deferral{}, ErrNotOwner
	}
	b.open.Remove(idKey(id))
	return d, nil
}

// MustCancel is Cancel but panics on error.
func (b *Book) MustCancel(id uint64, owner string) Deferral {
	d, err := b.Cancel(id, owner)
	if err != nil {
		panic(err)
	}
	return d
}

// Expire consumes a deferral that is past its expiry, reclaiming its
// storage. It is deliberately permissionless: an expired deferral can
// never be claimed again, so letting anyone clear it keeps a Book from
// silting up with dead entries that block Schedule against maxOpen.
//
// Fails with ErrInvalidNow, ErrNotFound, or ErrNotExpired (including for
// deferrals with no expiry, which never expire). On error nothing is
// modified.
func (b *Book) Expire(id uint64, now int64) (Deferral, error) {
	if now < 0 {
		return Deferral{}, ErrInvalidNow
	}
	d, ok := b.get(id)
	if !ok {
		return Deferral{}, ErrNotFound
	}
	if !d.IsExpired(now) {
		return Deferral{}, ErrNotExpired
	}
	b.open.Remove(idKey(id))
	return d, nil
}

// MustExpire is Expire but panics on error.
func (b *Book) MustExpire(id uint64, now int64) Deferral {
	d, err := b.Expire(id, now)
	if err != nil {
		panic(err)
	}
	return d
}

// Get returns an open deferral by ID. The second result is false if the
// deferral never existed or has already been consumed — Get cannot tell
// those apart, by design: consumed deferrals leave no tombstone.
//
// Get is a read-only preview and never authorizes anything. Only Claim's
// return value authorizes an action.
func (b *Book) Get(id uint64) (Deferral, bool) { return b.get(id) }

// Due returns up to limit open deferrals that are claimable at now, in
// ascending ID order (oldest first). A limit <= 0 returns nothing.
//
// It scans the open set, so its cost is bounded by MaxOpen.
func (b *Book) Due(now int64, limit int) []Deferral {
	out := []Deferral{}
	if limit <= 0 || now < 0 {
		return out
	}
	b.open.Iterate("", "", func(_ string, value any) bool {
		d := value.(Deferral)
		if d.IsClaimable(now) {
			out = append(out, d)
		}
		return len(out) >= limit
	})
	return out
}

// Expirable returns up to limit open deferrals that Expire would accept at
// now, in ascending ID order. A limit <= 0 returns nothing.
func (b *Book) Expirable(now int64, limit int) []Deferral {
	out := []Deferral{}
	if limit <= 0 || now < 0 {
		return out
	}
	b.open.Iterate("", "", func(_ string, value any) bool {
		d := value.(Deferral)
		if d.IsExpired(now) {
			out = append(out, d)
		}
		return len(out) >= limit
	})
	return out
}

// IterateOpen calls fn for every open deferral in ascending ID order.
// Iteration stops early when fn returns true.
//
// fn receives a COPY: Deferral is passed by value and holds only scalars
// and strings, so fn gets no pointer into the Book and cannot reach past
// it — Book's fields are all unexported.
//
// Two rules for fn, and the second is the one that is easy to miss.
//
//   - Do not Schedule, Claim, Cancel or Expire from inside fn: mutating
//     the tree while iterating it is undefined. Collect IDs first, then
//     act after IterateOpen returns.
//
//   - fn runs under the CALLING REALM'S STORAGE AUTHORITY. This method's
//     receiver is stamped with the importing realm's PkgID, so the borrow
//     rules leave the realm context set to that realm for the whole
//     callback, and a top-level fn has no receiver and no declaring realm
//     to anchor it elsewhere. A callback that re-enters the calling
//     realm's own mutators therefore does so with that realm's authority.
//     Never pass a caller-supplied function here from inside a
//     permission-gated path; pass only a closure this package's consumer
//     wrote itself.
func (b *Book) IterateOpen(fn func(Deferral) bool) {
	b.open.Iterate("", "", func(_ string, value any) bool {
		return fn(value.(Deferral))
	})
}

// get looks up an open deferral without touching the tree otherwise.
func (b *Book) get(id uint64) (Deferral, bool) {
	v := b.open.Get(idKey(id))
	if v == nil {
		return Deferral{}, false
	}
	return v.(Deferral), true
}

// idKey encodes an ID so that avl's lexical key order matches numeric ID
// order. math.MaxUint64 is 20 digits, so a fixed 20-wide zero-padded
// decimal is both sufficient and unambiguous.
func idKey(id uint64) string {
	s := strconv.FormatUint(id, 10)
	const width = 20
	if len(s) >= width {
		return s
	}
	return zeros[:width-len(s)] + s
}

const zeros = "00000000000000000000"

// checkedAdd returns a+b and reports whether the addition did not
// overflow int64.
func checkedAdd(a, b int64) (int64, bool) {
	sum := a + b
	if (b > 0 && sum < a) || (b < 0 && sum > a) {
		return 0, false
	}
	return sum, true
}

// Package duebook_demo is the reference consumer for the duebook
// scheduling primitive. It exists to make duebook's central claim
// falsifiable on a live chain.
//
// That claim is: a deferral claimed in transaction N is refused in
// transaction N+1, forever. A pure package cannot demonstrate this — a
// vm/qeval is a single ephemeral evaluation with no state that survives
// it. Only a realm, called twice, can show it. So this realm is not a
// decoration on the primitive; it is the experiment.
//
// # What it does
//
// Anyone schedules an announcement to be published no earlier than
// delayBlocks from now. Once due, ANYONE may publish it — publication is
// deliberately permissionless, so that what protects the announcement from
// being published twice is duebook's exactly-once Claim and nothing else.
// If an access-control list were guarding Publish, the experiment would
// prove nothing about duebook.
//
// The scheduler may cancel at any time before publication. Once the
// optional time-to-live elapses, the announcement can never be published
// and anyone may clear it to free a slot.
//
// # How it wires duebook correctly
//
// This realm is also the worked example of duebook's consumer contract:
//
//   - the clock is runtime.ChainHeight(), never a call argument (contract 1);
//   - heights are the only unit used (contract 2);
//   - the *Book is an unexported package-level var and is never returned
//     across a realm boundary (contract 3);
//   - the owner is cur.Previous().Address(), never a parameter (contract 4);
//   - Publish performs its effect immediately after a successful Claim, in
//     the same transaction (contract 5).
//
// This realm holds no coins and has no admin. Every entrypoint rejects
// attached coins.
package duebook_demo

import (
	"chain"
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"

	"gno.land/p/g1ut6uspuh73e02yauxpmyt8g3wwddaq8utagvm3/duebook"
	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/markdown/sanitize/v0"
)

const (
	// MinDelayBlocks is the floor on how far ahead an announcement may be
	// scheduled. One block is enough to prove the delay is enforced while
	// keeping the realm exercisable on a live chain.
	MinDelayBlocks = int64(1)

	// MaxDelayBlocks caps scheduling roughly 100 days out at pearl-1's
	// ~3.42s blocks. It also bounds now+delay well inside int64.
	MaxDelayBlocks = int64(2_500_000)

	// MaxTTLBlocks caps how long a due announcement stays publishable.
	MaxTTLBlocks = int64(2_500_000)

	// MaxOpen caps simultaneously scheduled announcements, bounding both
	// storage and the cost of the Due/Expirable scans.
	MaxOpen = 200

	// MaxTextLen bounds one announcement. It is a BYTE length, not a rune
	// count, because its job is to bound storage; a multi-byte script
	// therefore gets fewer than 280 visible characters.
	MaxTextLen = 280

	// MaxPublishedKept is how many recent publications Render shows. The
	// permanent record is the emitted event; this is a bounded window so
	// realm storage cannot grow without limit.
	MaxPublishedKept = 50

	// MaxListed caps how many entries a single query returns.
	MaxListed = 50
)

// book holds the scheduled announcements. It is unexported and never
// returned: handing a *Book across a realm boundary would hand out the
// right to schedule, cancel and claim (duebook consumer contract 3).
var book = duebook.MustNew(MinDelayBlocks, MaxDelayBlocks, MaxOpen)

// publication is one published announcement, kept for rendering.
type publication struct {
	seq         int64
	deferralID  int64
	scheduler   address
	publisher   address
	text        string
	scheduledAt int64
	dueAt       int64
	publishedAt int64
}

var (
	published      = avl.NewTree() // padded seq -> *publication
	publishedTotal int64           // every publication ever, including evicted
	nextSeq        int64 = 1
)

// rejectStraySend aborts if an EOA attached coins to an entrypoint that
// has no use for them. This realm never holds value; without this guard a
// mistyped send would be silently absorbed by the realm bank.
func rejectStraySend(cur realm) {
	if cur.Previous().IsUserCall() && len(unsafe.OriginSend()) > 0 {
		panic("this entrypoint does not accept coins")
	}
}

// Schedule registers an announcement to be published no earlier than
// delayBlocks from the current height, and returns its deferral ID.
//
// ttlBlocks is how long after the due height the announcement stays
// publishable; 0 means it never expires. The caller becomes the owner and
// is the only account that may Cancel it.
func Schedule(cur realm, text string, delayBlocks, ttlBlocks int64) string {
	rejectStraySend(cur)

	if text == "" {
		panic("announcement text must not be empty")
	}
	if len(text) > MaxTextLen {
		panic("announcement text exceeds " + itoa(MaxTextLen) + " bytes")
	}
	if ttlBlocks < 0 || ttlBlocks > MaxTTLBlocks {
		panic("ttlBlocks out of range [0, " + itoa(MaxTTLBlocks) + "]")
	}

	owner := cur.Previous().Address()
	// The clock is the chain's, never an argument (consumer contract 1).
	now := runtime.ChainHeight()

	// duebook validates delayBlocks against the book's own bounds and
	// returns an error rather than panicking; a realm turns that into an
	// aborted transaction so nothing is half-applied.
	id, err := book.Schedule(owner.String(), text, now, delayBlocks, ttlBlocks)
	if err != nil {
		panic(err)
	}

	d, _ := book.Get(id)
	chain.Emit("Scheduled",
		"id", utoa(id),
		"scheduler", owner.String(),
		"dueAt", itoa(d.DueAt),
		"expiresAt", itoa(d.ExpiresAt),
	)
	return utoa(id)
}

// Publish publishes a scheduled announcement once it is due. It is
// deliberately permissionless: duebook's exactly-once Claim is the only
// thing preventing a second publication, which is precisely what this
// realm exists to demonstrate.
//
// Aborts if the announcement does not exist, is not due yet, has expired,
// or has already been consumed by a publication or a cancellation.
func Publish(cur realm, id int64) string {
	rejectStraySend(cur)

	did := mustID(id)
	now := runtime.ChainHeight()

	// CONSUME FIRST. Claim removes the deferral before returning, so by
	// the time the effect below runs, no second Claim of this ID can ever
	// succeed — in this transaction or any future one.
	d, err := book.Claim(did, now)
	if err != nil {
		panic(err)
	}

	// EFFECT SECOND, same transaction (consumer contract 5).
	publisher := cur.Previous().Address()
	seq := nextSeq
	nextSeq++
	publishedTotal++

	published.Set(seqKey(seq), &publication{
		seq:         seq,
		deferralID:  int64(d.ID),
		scheduler:   address(d.Owner),
		publisher:   publisher,
		text:        d.Payload,
		scheduledAt: d.CreatedAt,
		dueAt:       d.DueAt,
		publishedAt: now,
	})
	evictOldest()

	chain.Emit("Published",
		"id", utoa(d.ID),
		"seq", itoa(seq),
		"scheduler", d.Owner,
		"publisher", publisher.String(),
		"height", itoa(now),
	)
	return "published " + utoa(d.ID) + " at height " + itoa(now)
}

// Cancel withdraws a scheduled announcement before it is published. Only
// the account that scheduled it may cancel, and only while it is still
// open — a cancellation that arrives after publication aborts.
func Cancel(cur realm, id int64) string {
	rejectStraySend(cur)

	did := mustID(id)
	caller := cur.Previous().Address()

	// Ownership is checked by duebook against the address this realm
	// recorded at Schedule, never against a caller-supplied argument.
	d, err := book.Cancel(did, caller.String())
	if err != nil {
		panic(err)
	}

	chain.Emit("Cancelled", "id", utoa(d.ID), "scheduler", d.Owner)
	return "cancelled " + utoa(d.ID)
}

// Expire clears an announcement whose time-to-live has elapsed, freeing
// its slot against MaxOpen. It is permissionless because an expired
// announcement can never be published, so there is nothing left to
// protect and everything to gain from letting anyone tidy up.
func Expire(cur realm, id int64) string {
	rejectStraySend(cur)

	did := mustID(id)
	now := runtime.ChainHeight()

	d, err := book.Expire(did, now)
	if err != nil {
		panic(err)
	}

	chain.Emit("Expired", "id", utoa(d.ID), "scheduler", d.Owner, "height", itoa(now))
	return "expired " + utoa(d.ID)
}

// --- read-only views -------------------------------------------------------
// None of these authorize anything: only Publish's successful Claim does.

// Height returns the chain height this realm is reading as "now".
func Height() int64 { return runtime.ChainHeight() }

// OpenCount returns how many announcements are currently scheduled.
func OpenCount() int { return book.OpenCount() }

// PublishedTotal returns how many announcements have ever been published,
// including ones since evicted from the rendered window.
func PublishedTotal() int64 { return publishedTotal }

// NextID returns the deferral ID the next Schedule will allocate. It only
// ever increases; that is what makes a consumed ID permanently unusable.
func NextID() string { return utoa(book.NextID()) }

// Status describes a scheduled announcement: its window, and whether it is
// publishable right now. Returns "unknown" when the ID was never issued or
// has already been consumed — duebook keeps no tombstone, so those two
// cases are indistinguishable by design.
func Status(id int64) string {
	if id < 1 {
		return "unknown"
	}
	d, ok := book.Get(uint64(id))
	if !ok {
		return "unknown"
	}
	now := runtime.ChainHeight()
	state := "pending"
	switch {
	case d.IsExpired(now):
		state = "expired"
	case d.IsDue(now):
		state = "publishable"
	}
	out := state +
		" scheduler=" + d.Owner +
		" dueAt=" + itoa(d.DueAt) +
		" now=" + itoa(now)
	if d.ExpiresAt == 0 {
		return out + " expiresAt=never"
	}
	return out + " expiresAt=" + itoa(d.ExpiresAt)
}

// DueNow returns the IDs of announcements publishable at the current
// height, oldest first, capped at MaxListed.
func DueNow() string {
	ds := book.Due(runtime.ChainHeight(), MaxListed)
	if len(ds) == 0 {
		return ""
	}
	out := ""
	for i, d := range ds {
		if i > 0 {
			out += ","
		}
		out += utoa(d.ID)
	}
	return out
}

// ExpirableNow returns the IDs that Expire would accept at the current
// height, oldest first, capped at MaxListed.
func ExpirableNow() string {
	ds := book.Expirable(runtime.ChainHeight(), MaxListed)
	if len(ds) == 0 {
		return ""
	}
	out := ""
	for i, d := range ds {
		if i > 0 {
			out += ","
		}
		out += utoa(d.ID)
	}
	return out
}

// --- rendering -------------------------------------------------------------

// realmPath is this realm's gnoweb prefix, used to build view links.
const realmPath = "/r/g1ut6uspuh73e02yauxpmyt8g3wwddaq8utagvm3/duebook_demo"

// Render serves three views, selected by path. Anyone may Schedule, so
// the default view must not be something a stranger can inflate: it
// shows only what is publishable right now, capped at MaxListed. The
// full scheduled table lives behind :open and is capped too, so no view
// is unbounded and none of them is the landing page by default.
//
//	(empty)  summary + publishable now + recent publications
//	open     every scheduled announcement, up to MaxListed rows
//	about    what this realm is and why it exists
func Render(path string) string {
	switch normalizePath(path) {
	case "open":
		return renderHeader() + renderOpen()
	case "about":
		return renderHeader() + renderAbout()
	default:
		return renderHeader() + renderDue() + renderPublished()
	}
}

func renderHeader() string {
	now := runtime.ChainHeight()
	s := "# Scheduled announcements\n\n"
	s += "Reference consumer for [duebook](/p/g1ut6uspuh73e02yauxpmyt8g3wwddaq8utagvm3/duebook).\n\n"
	s += "- height: " + itoa(now) + "\n"
	s += "- scheduled: " + itoa(int64(book.OpenCount())) + " / " + itoa(int64(MaxOpen)) + "\n"
	s += "- published (total): " + itoa(publishedTotal) + "\n"
	s += "- next id: " + utoa(book.NextID()) + "\n\n"
	s += "[summary](" + realmPath + ") · "
	s += "[all scheduled](" + realmPath + ":open) · "
	s += "[about](" + realmPath + ":about)\n\n"
	return s
}

// renderDue lists only what can be published at this height. book.Due
// applies the cap itself, so the slice is at most MaxListed long.
func renderDue() string {
	now := runtime.ChainHeight()
	ds := book.Due(now, MaxListed)

	s := "## Publishable now\n\n"
	if len(ds) == 0 {
		s += "_nothing is due at height " + itoa(now) + "._\n\n"
		return s
	}
	s += renderRows(ds, now)
	if book.OpenCount() > len(ds) {
		s += "\n" + itoa(int64(book.OpenCount()-len(ds))) +
			" more scheduled — see [all scheduled](" + realmPath + ":open).\n"
	}
	return s + "\n"
}

// renderOpen lists the whole book, stopping at MaxListed rows so this
// view has a fixed ceiling independent of MaxOpen.
func renderOpen() string {
	now := runtime.ChainHeight()

	s := "## Scheduled\n\n"
	if book.OpenCount() == 0 {
		return s + "_none_\n\n"
	}
	ds := []duebook.Deferral{}
	book.IterateOpen(func(d duebook.Deferral) bool {
		ds = append(ds, d)
		return len(ds) >= MaxListed
	})
	s += renderRows(ds, now)
	if book.OpenCount() > len(ds) {
		s += "\nShowing the first " + itoa(int64(len(ds))) + " of " +
			itoa(int64(book.OpenCount())) + ".\n"
	}
	return s + "\n"
}

func renderRows(ds []duebook.Deferral, now int64) string {
	s := "| id | scheduler | due at | expires | state |\n"
	s += "|---|---|---|---|---|\n"
	for _, d := range ds {
		state := "pending"
		switch {
		case d.IsExpired(now):
			state = "expired"
		case d.IsDue(now):
			state = "**publishable**"
		}
		exp := "never"
		if d.ExpiresAt != 0 {
			exp = itoa(d.ExpiresAt)
		}
		s += "| " + utoa(d.ID) +
			" | " + sanitize.InlineText(d.Owner) +
			" | " + itoa(d.DueAt) +
			" | " + exp +
			" | " + state + " |\n"
	}
	return s
}

// renderPublished shows the retained window, which evictOldest already
// holds at MaxPublishedKept entries.
func renderPublished() string {
	s := "## Published\n\n"
	if published.Size() == 0 {
		return s + "_none_\n\n"
	}
	s += "Most recent " + itoa(int64(MaxPublishedKept)) + " shown; the full record is in the emitted events.\n\n"
	published.Iterate("", "", func(_ string, v any) bool {
		p := v.(*publication)
		s += "**#" + itoa(p.seq) + "** (deferral " + itoa(p.deferralID) + ")"
		s += " scheduled at " + itoa(p.scheduledAt)
		s += ", due " + itoa(p.dueAt)
		s += ", published " + itoa(p.publishedAt) + "\n\n"
		// Blockquote, not InlineText: the slot IS a blockquote, and
		// the helper must be the one whose contract covers the slot.
		// InlineText happens to fold newlines today, which would
		// contain the payload by side effect — relying on that makes
		// safety version-bound to a helper that never promised it.
		// Blockquote emits its own "\n" ... "\n\n" envelope, so no
		// manual "> " prefix here (the helpers are not idempotent).
		s += sanitize.Blockquote(p.text)
		s += "by " + sanitize.InlineText(p.scheduler.String())
		s += " · published by " + sanitize.InlineText(p.publisher.String()) + "\n\n"
		return false
	})
	return s
}

func renderAbout() string {
	return "## About\n\n" +
		"Anyone may schedule an announcement to be published no earlier than " +
		"`delayBlocks` from now. Once due, **anyone** may publish it — " +
		"publication is deliberately permissionless, so the only thing " +
		"preventing a second publication is duebook's exactly-once `Claim`. " +
		"That is the experiment this realm exists to run.\n\n" +
		"The scheduler may cancel any time before publication. Once the " +
		"optional time-to-live elapses the announcement can never be " +
		"published, and anyone may clear it to free a slot.\n\n" +
		"This realm holds no coins and has no admin. Every entrypoint " +
		"rejects attached coins.\n\n" +
		"- min / max delay: " + itoa(MinDelayBlocks) + " / " + itoa(MaxDelayBlocks) + " blocks\n" +
		"- max time-to-live: " + itoa(MaxTTLBlocks) + " blocks\n" +
		"- max open at once: " + itoa(int64(MaxOpen)) + "\n" +
		"- max announcement length: " + itoa(int64(MaxTextLen)) + " bytes\n"
}

// normalizePath reduces a gnoweb render path to a bare view name, so
// "", "/", "open" and "/open/" all select the same view.
func normalizePath(path string) string {
	for len(path) > 0 && path[0] == '/' {
		path = path[1:]
	}
	for len(path) > 0 && path[len(path)-1] == '/' {
		path = path[:len(path)-1]
	}
	return path
}

// --- helpers ---------------------------------------------------------------

// mustID converts an exported int64 ID to duebook's uint64 form. IDs start
// at 1, so anything below that was never issued.
func mustID(id int64) uint64 {
	if id < 1 {
		panic("id must be positive")
	}
	return uint64(id)
}

// evictOldest trims the rendered window to MaxPublishedKept, dropping the
// lowest sequence numbers first. Evicted publications remain in the
// emitted events.
func evictOldest() {
	for published.Size() > MaxPublishedKept {
		oldest := ""
		published.Iterate("", "", func(key string, _ any) bool {
			oldest = key
			return true // first key in ascending order
		})
		if oldest == "" {
			return
		}
		published.Remove(oldest)
	}
}

// seqKey encodes a sequence number so avl's lexical order matches numeric
// order. Sequences are positive int64, at most 19 digits.
func seqKey(seq int64) string {
	s := strconv.FormatInt(seq, 10)
	const width = 19
	if len(s) >= width {
		return s
	}
	return "0000000000000000000"[:width-len(s)] + s
}

func itoa(n int64) string  { return strconv.FormatInt(n, 10) }
func utoa(n uint64) string { return strconv.FormatUint(n, 10) }
